using GraphApi.Models.USR.RazasMascota;namespace GraphApi.Services.USR.RazasMascota{    /// <summary>    /// Define las operaciones de negocio y persistencia para RazasMascotas.    /// </summary>    public interface IRazasMascotaService    {        /// <summary>        /// Obtiene la lista de RazasMascotas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadRazasMascota>> GetRazasMascotas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de RazasMascotas con filtros opcionales.        /// </summary>        /// <param name="razaMascotaID">Filtro opcional para RazaMascotaID.</param>        /// <param name="tipoMascotaID">Filtro opcional para TipoMascotaID.</param>        /// <param name="razaMascota">Filtro opcional para RazaMascota.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetRazasMascotasDynamic(            int? razaMascotaID,            int? tipoMascotaID,            string? razaMascota,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo RazasMascota.        /// </summary>        /// <param name="objInput">Datos para crear el RazasMascota.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadRazasMascota> CreateRazasMascota(            clCreateRazasMascota objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un RazasMascota.        /// </summary>        /// <param name="objInput">Datos para actualizar el RazasMascota, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadRazasMascota?> UpdateRazasMascota(            clUpdateRazasMascota objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un RazasMascota por su ID.        /// </summary>        /// <param name="nRazasMascotaID">ID del RazasMascota a eliminar.</param>        Task<bool> DeleteRazasMascota(int nRazasMascotaID);    }}